b.Text // سبب أو محفز الانتكاسة\n  trigger       String?\n  notes         String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, abstinenceTrackerId, startedAt])\n  @@index([userId, endedAt])\n  @@map(\"abstinence_session\")\n}\n\n// -----------------------------------------------------------------------------\n// 10. LOCAL-FIRST MUTATION RECEIPTS & IDEMPOTENCY\n// -----------------------------------------------------------------------------\n\nmodel MutationReceipt {\n  id         String   @id // Client-generated mutation UUID\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  entityType String // \"task\", \"tracker\", \"entry\", etc.\n  entityId   String\n  action     String // \"create\", \"update\", \"delete\", \"toggle\"\n  createdAt  DateTime @default(now())\n\n  @@unique([userId, id])\n  @@index([userId, createdAt])\n  @@map(\"mutation_receipt\")\n}\n\n// -----------------------------------------------------------------------------\n// 11. DEDICATED DOMAIN MODELS (MIGRATED FROM LEGACY LOCALSTORAGE)\n// -----------------------------------------------------------------------------\n\nmodel GymWorkout {\n  id              String   @id @default(cuid())\n  userId          String\n  user            User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  date            String // Local calendar date \"YYYY-MM-DD\"\n  title           String // e.g. \"تمارين الصدر والترايسبس\"\n  muscleGroup     String? // e.g. \"push\", \"pull\", \"legs\"\n  durationMinutes Int?     @default(60)\n  exercises       Json     @default(\"[]\") // [{ name, sets: [{ reps, weight, completed }] }]\n  notes           String?  @db.Text\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([userId, date])\n  @@map(\"gym_workout\")\n}\n\nmodel MealEntry {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  date      String // Local calendar date \"YYYY-MM-DD\"\n  mealType  String // \"breakfast\", \"lunch\", \"dinner\", \"snacks\"\n  title     String\n  calories  Int      @default(0)\n  protein   Float    @default(0)\n  carbs     Float    @default(0)\n  fat       Float    @default(0)\n  notes     String?  @db.Text\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, date])\n  @@map(\"meal_entry\")\n}\n\nmodel ExpenseEntry {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  date      String // Local calendar date \"YYYY-MM-DD\"\n  title     String\n  amount    Float\n  category  String // e.g. \"طعام ومطاعم\", \"مشتريات\", \"فواتير\"\n  notes     String?  @db.Text\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, date])\n  @@map(\"expense_entry\")\n}\n\n// -----------------------------------------------------------------------------\n// 12. DEDICATED PRAYER TRACKING (FIRST-CLASS DOMAIN)\n// -----------------------------------------------------------------------------\n\nmodel PrayerRecord {\n  id          String    @id @default(cuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  date        String // Local calendar date \"YYYY-MM-DD\"\n  prayerKey   String // \"fajr\" | \"dhuhr\" | \"asr\" | \"maghrib\" | \"isha\"\n  isCompleted Boolean   @default(false)\n  completedAt DateTime?\n  location    String? // \"mosque\" | \"home\" | \"work\" | \"other\"\n  withSunnah  Boolean   @default(false)\n  notes       String?   @db.Text\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@unique([userId, date, prayerKey])\n  @@index([userId, date])\n  @@map(\"prayer_record\")\n}\n",
